-- APPLIED/LIVE SAFE CATALOG — LAB Virtual tools only.
-- Idempotent: contains no economic rewards.
do $$ declare p uuid; begin
select id into p from public.platforms where code='lab-virtual';
if p is null then raise exception 'platform lab-virtual missing'; end if;
on conflict(platform_id,activity_id) do update set name=excluded.name,reward_policy=excluded.reward_policy,max_xp=0,max_points=0,max_coins=0,repeatable=false,active=true,metadata=excluded.metadata;
end $$;
